58	/** Converts the old message update to the new schema */
59	function convertMessageUpdate(message: Message, update: OldMessageUpdate): MessageUpdate | null {
60		try {
61			// Text and files
62			if (update.type === "finalAnswer") {
63				return {
64					type: MessageUpdateType.FinalAnswer,
65					text: update.text,
66					interrupted: message.interrupted ?? false,
67				};
68			} else if (update.type === "stream") {
69				return {
70					type: MessageUpdateType.Stream,
71					token: update.token,
72				};
73			} else if (update.type === "file") {
74				return {
75					type: MessageUpdateType.File,
76					name: "Unknown",
77					sha: update.sha,
78					// assume jpeg but could be any image. should be harmless
79					mime: "image/jpeg",
80				};
81			}
82	
83			// Status
84			else if (update.type === "status") {
85				if (update.status === "title") {
86					return {
87						type: MessageUpdateType.Title,
88						title: update.message ?? "New Chat",
89					};
90				}
91				if (update.status === "pending") return null;
92	
93				const status =
94					update.status === "started"
95						? MessageUpdateStatus.Started
96						: update.status === "finished"
97							? MessageUpdateStatus.Finished
98							: MessageUpdateStatus.Error;
99				return {
100					type: MessageUpdateType.Status,
101					status,
102					message: update.message,
103				};
104			} else if (update.type === "error") {
105				// Treat it as an error status update
106				return {
107					type: MessageUpdateType.Status,
108					status: MessageUpdateStatus.Error,
109					message: update.message,
110				};
111			}
112	
113			// Web Search
114			else if (update.type === "webSearch") {
115				return null; // Web search updates are no longer supported
116			}
117			console.warn("Unknown message update during migration:", update);
118			return null;
119		} catch (error) {
120			console.error("Error converting message update during migration. Skipping it... Error:", error);
121			return null;
122		}
123	}
