10	async function deleteBatch(conversations: Collection<Conversation>, ids: ObjectId[]) {
11		if (ids.length === 0) return 0;
12		const deleteResult = await conversations.deleteMany({ _id: { $in: ids } });
13		return deleteResult.deletedCount;
14	}
