16	async function processCursor<T>(
17		cursor: FindCursor<T>,
18		processBatchFn: (batch: T[]) => Promise<void>
19	) {
20		let batch = [];
21		while (await cursor.hasNext()) {
22			const doc = await cursor.next();
23			if (doc) {
24				batch.push(doc);
25			}
26			if (batch.length >= BATCH_SIZE) {
27				await processBatchFn(batch);
28				batch = [];
29			}
30		}
31		if (batch.length > 0) {
32			await processBatchFn(batch);
33		}
34	}
