36	export async function deleteConversations(
37		collections: typeof import("$lib/server/database").collections
38	) {
39		let deleteCount = 0;
40		const { conversations, sessions } = collections;
41	
42		// First criteria: Delete conversations with no user/assistant messages older than 1 hour
43		const emptyConvCursor = conversations
44			.find({
45				"messages.from": { $not: { $in: ["user", "assistant"] } },
46				createdAt: { $lt: new Date(Date.now() - DELETE_THRESHOLD_MS) },
47			})
48			.batchSize(BATCH_SIZE);
49	
50		await processCursor(emptyConvCursor, async (batch) => {
51			const ids = batch.map((doc) => doc._id);
52			deleteCount += await deleteBatch(conversations, ids);
53		});
54	
55		// Second criteria: Process conversations without users in batches and check sessions
56		const noUserCursor = conversations.find({ userId: { $exists: false } }).batchSize(BATCH_SIZE);
57	
58		await processCursor(noUserCursor, async (batch) => {
59			const sessionIds = [
60				...new Set(batch.map((conv) => conv.sessionId).filter((id): id is string => !!id)),
61			];
62	
63			const existingSessions = await sessions.find({ sessionId: { $in: sessionIds } }).toArray();
64			const validSessionIds = new Set(existingSessions.map((s) => s.sessionId));
65	
66			const invalidConvs = batch.filter(
67				(conv) => !conv.sessionId || !validSessionIds.has(conv.sessionId)
68			);
69			const idsToDelete = invalidConvs.map((conv) => conv._id);
70			deleteCount += await deleteBatch(conversations, idsToDelete);
71		});
72	
73		logger.info(`[MIGRATIONS] Deleted ${deleteCount} conversations in total.`);
74		return deleteCount;
75	}
